// GENERATED by scripts/sync-readiness.mjs from apps/api/src/worker/security-scan.ts. Do not edit.
/* eslint-disable */

import type { AndroidSecurity, IosSecurity, SecretHit, SecretKind, SecurityFacts } from './readiness.gen';

// Security scan facts, gathered at upload next to the readiness facts (worker/facts.ts). The findings are made
// from them on every read (readiness/security.ts). Hardcoded secrets are matched on high confidence patterns
// only, and only the kind, the file and a masked value (first 4 and last 4 characters) are ever kept: the full
// value never leaves this file, is not stored and is not logged. Size, file count and time caps keep a large
// build from stalling the worker; when one stops the scan early, `scan.capped` says so.
//
// This file has no imports (Node globals only) and reads the archive through ScanZip, so the same scan runs in
// the worker (yauzl, worker/security.ts) and in the CLI on a local file (`appforshare check`, rival 12 item 5):
// scripts/sync-readiness.mjs copies it into packages/cli. Keep it free of imports.

type Dict = Record<string, unknown>;

/** Caps of one scan. Exported so tests can make them small. */
export const LIMITS = {
  /** Bytes read across every file. */
  totalBytes: 400 * 1024 * 1024,
  /** Bytes read from one file (the rest of a larger file is skipped). */
  fileBytes: 256 * 1024 * 1024,
  files: 800,
  /** Wall clock time of one scan. */
  ms: 25_000,
};
export type ScanLimits = typeof LIMITS;

/** The archive, as the scan reads it. Names are full entry paths without directories. */
export type ScanZip = {
  names(): string[];
  /** Uncompressed size of an entry. */
  size(name: string): number;
  /** The whole entry, up to `max` bytes (null when it is larger or unreadable). */
  read(name: string, max: number): Promise<Uint8Array | null>;
  /** The first `bytes` of an entry. */
  head(name: string, bytes: number): Promise<Uint8Array>;
  /** The inflated entry as chunks; breaking out of the loop stops the read. */
  stream(name: string): Promise<AsyncIterable<Uint8Array>>;
};

const MAX_SECRETS = 30;
const MAX_GOOGLE_KEYS = 5;
const MAX_LIBS = 200;
const MAX_EXPORTED = 20;
/** Text kept from the end of one chunk for the next, so a match split across two chunks is still seen. */
const OVERLAP = 4096;

const buf = (b: Uint8Array): Buffer => (Buffer.isBuffer(b) ? b : Buffer.from(b.buffer, b.byteOffset, b.byteLength));

// ---------------------------------------------------------------- secret patterns

type SecretRule = { kind: SecretKind; re: RegExp; value?: (m: RegExpMatchArray) => string };

/** High confidence patterns only. Lookarounds stop a match inside a longer token. */
export const SECRET_RULES: SecretRule[] = [
  { kind: 'aws-access-key', re: /(?<![A-Z0-9])AKIA[0-9A-Z]{16}(?![A-Z0-9])/g },
  { kind: 'stripe-live-secret', re: /(?<![A-Za-z0-9_])[sr]k_live_[0-9A-Za-z]{24,247}(?![0-9A-Za-z])/g },
  {
    kind: 'private-key',
    re: /-----BEGIN (?:RSA |EC |DSA |OPENSSH |ENCRYPTED )?PRIVATE KEY-----(?:\\n|\\r|\s)*([A-Za-z0-9+/]{40,4096}={0,2})/g,
    value: (m) => m[1],
  },
  { kind: 'slack-token', re: /(?<![A-Za-z0-9])xox[abposr]-[0-9]{8,14}-[0-9A-Za-z-]{10,80}(?![0-9A-Za-z])/g },
  { kind: 'slack-webhook', re: /https:\/\/hooks\.slack\.com\/services\/T[A-Z0-9]{6,12}\/B[A-Z0-9]{6,12}\/[A-Za-z0-9]{20,32}(?![A-Za-z0-9])/g },
  { kind: 'github-token', re: /(?<![A-Za-z0-9_])(?:gh[pousr]_[A-Za-z0-9]{36}|github_pat_[A-Za-z0-9_]{60,100})(?![A-Za-z0-9_])/g },
  { kind: 'firebase-server-key', re: /(?<![A-Za-z0-9_-])AAAA[A-Za-z0-9_-]{7}:APA91b[A-Za-z0-9_-]{120,160}(?![A-Za-z0-9_-])/g },
  { kind: 'google-api-key', re: /(?<![A-Za-z0-9_-])AIza[0-9A-Za-z_-]{35}(?![0-9A-Za-z_-])/g },
];

/** Values that are documentation samples or placeholders, not keys. */
const PLACEHOLDER = /EXAMPLE|SAMPLE|PLACEHOLDER|DUMMY|YOUR_?KEY|X{6,}|x{6,}|\*{3,}|0{12,}/;
const SA_EMAIL = /"client_email"\s*:\s*"([^"@\s]{1,100}@[a-z0-9-]{1,63}\.iam\.gserviceaccount\.com)"/g;
const SA_KEY = /"private_key"\s*:\s*"-----BEGIN/;

/** First 4 and last 4 characters; never the whole value. */
export function mask(v: string): string {
  return v.length <= 12 ? '****' : `${v.slice(0, 4)}...${v.slice(-4)}`;
}

// ---------------------------------------------------------------- markers

/** Type descriptors in dex code of root, tamper and attestation libraries. */
const DEX_RASP: [string, string][] = [
  ['Lcom/scottyab/rootbeer/', 'RootBeer'],
  ['Lcom/aheaditec/talsec', 'freeRASP (Talsec)'],
  ['Lcom/guardsquare/dexguard/runtime/', 'DexGuard runtime'],
  ['Lcom/gantix/JailMonkey/', 'JailMonkey'],
  ['Lcom/google/android/play/core/integrity/', 'Play Integrity API'],
  ['Lcom/google/firebase/appcheck/', 'Firebase App Check'],
];
/** Class and symbol names in an iOS binary. */
const IOS_RASP: [string, string][] = [
  ['DCAppAttestService', 'App Attest'],
  ['IOSSecuritySuite', 'IOSSecuritySuite'],
  ['TalsecRuntime', 'freeRASP (Talsec)'],
  ['JailMonkey', 'JailMonkey'],
  ['FIRAppCheck', 'Firebase App Check'],
];
/** Embedded frameworks that are such libraries. */
const IOS_RASP_FRAMEWORKS: [RegExp, string][] = [
  [/^IOSSecuritySuite$/i, 'IOSSecuritySuite'],
  [/^(TalsecRuntime|freerasp)$/i, 'freeRASP (Talsec)'],
  [/^FirebaseAppCheck$/i, 'Firebase App Check'],
  [/^JailMonkey$/i, 'JailMonkey'],
];

const OKHTTP = /okhttp\/(\d{1,2}\.\d{1,3}\.\d{1,3})(?![\d.])/g;
const OPENSSL = /OpenSSL (\d\.\d\.\d{1,2}[a-z]{0,2})[ -]/g;
const ZLIB = / inflate (\d\.\d{1,2}\.\d{1,2}(?:\.\d{1,2})?) Copyright/g;
const GET_TASK_ALLOW = /<key>get-task-allow<\/key>\s*<(true|false)\s*\/>/;

const MEDIA = /\.(png|jpe?g|gif|webp|heic|heif|bmp|ico|mp3|mp4|m4a|m4v|aac|wav|ogg|oga|opus|caf|aiff?|mov|webm|ttf|otf|ttc|woff2?|car|nib|zip|gz|br|jar|aar|tflite|onnx|pb|ress|resource|assets|unity3d|bank|pak|obb|dylib)$/i;

// ---------------------------------------------------------------- scan state

type Opts = { dex?: boolean; native?: boolean; iosBinary?: boolean; utf16?: boolean };

export class Scan {
  readonly secrets = new Map<string, SecretHit>();
  readonly googleKeys = new Map<string, SecretHit>();
  readonly rasp = new Set<string>();
  readonly libs = new Map<string, { name: string; version: string }>();
  webview = false;
  getTaskAllow: boolean | null = null;
  files = 0;
  bytes = 0;
  capped = false;
  private readonly until: number;
  private sa: { email: string | null; key: boolean } = { email: null, key: false };

  constructor(private readonly limits: ScanLimits = LIMITS) {
    this.until = Date.now() + limits.ms;
  }

  get stopped(): boolean {
    return this.bytes >= this.limits.totalBytes || this.files >= this.limits.files || Date.now() > this.until;
  }

  /** Bytes the next file may read. */
  allowance(): number {
    return Math.max(0, Math.min(this.limits.fileBytes, this.limits.totalBytes - this.bytes));
  }

  lib(name: string, version: string) {
    if (this.libs.size < MAX_LIBS && /^[\w.+-]{1,40}$/.test(version)) this.libs.set(`${name}@${version}`, { name, version });
  }

  /** Looks at one window of a file's text. */
  look(text: string, file: string, o: Opts) {
    this.match(text, file);
    if (o.utf16 && text.includes('\0')) this.match(text.replace(/\0/g, ''), file);
    if (o.dex) {
      for (const [needle, name] of DEX_RASP) if (text.includes(needle)) this.rasp.add(name);
      if (text.includes('setWebContentsDebuggingEnabled')) this.webview = true;
      for (const m of text.matchAll(OKHTTP)) this.lib('com.squareup.okhttp3:okhttp', m[1]);
    }
    if (o.native || o.iosBinary) {
      for (const m of text.matchAll(OPENSSL)) this.lib('openssl', m[1]);
      for (const m of text.matchAll(ZLIB)) this.lib('zlib', m[1]);
    }
    if (o.iosBinary) {
      for (const [needle, name] of IOS_RASP) if (text.includes(needle)) this.rasp.add(name);
      const g = GET_TASK_ALLOW.exec(text);
      if (g) this.getTaskAllow = g[1] === 'true';
    }
  }

  private match(text: string, file: string) {
    for (const rule of SECRET_RULES) {
      rule.re.lastIndex = 0;
      for (const m of text.matchAll(rule.re)) {
        const v = rule.value ? rule.value(m) : m[0];
        if (PLACEHOLDER.test(v)) continue;
        const hit: SecretHit = { kind: rule.kind, file, masked: mask(v) };
        const key = `${hit.kind}|${file}|${hit.masked}`;
        if (rule.kind === 'google-api-key') {
          if (this.googleKeys.size < MAX_GOOGLE_KEYS * 4 && !this.googleKeys.has(key)) this.googleKeys.set(key, hit);
        } else if (this.secrets.size < MAX_SECRETS && !this.secrets.has(key)) this.secrets.set(key, hit);
      }
    }
    if (text.includes('gserviceaccount.com')) {
      for (const m of text.matchAll(SA_EMAIL)) this.sa.email = m[1];
    }
    if (!this.sa.key && SA_KEY.test(text)) this.sa.key = true;
  }

  /** Called when a file is done: a service account JSON replaces the bare private key hit of the same file. */
  endFile(file: string) {
    if (this.sa.email && this.sa.key) {
      for (const [k, h] of this.secrets) if (h.file === file && h.kind === 'private-key') this.secrets.delete(k);
      const hit: SecretHit = { kind: 'google-service-account', file, masked: mask(this.sa.email) };
      const key = `${hit.kind}|${file}|${hit.masked}`;
      if (this.secrets.size < MAX_SECRETS) this.secrets.set(key, hit);
    }
    this.sa = { email: null, key: false };
  }

  /** Reads one zip entry in chunks (never the whole file in memory) and looks at each window. */
  async entry(zip: ScanZip, name: string, o: Opts = {}): Promise<void> {
    if (this.stopped) {
      this.capped = true;
      return;
    }
    const max = this.allowance();
    const size = zip.size(name);
    if (size > max) this.capped = true;
    this.files++;
    let chunks: AsyncIterable<Uint8Array>;
    try {
      chunks = await zip.stream(name);
    } catch {
      return;
    }
    let tail = '';
    let read = 0;
    try {
      for await (const chunk of chunks) {
        const b = buf(chunk);
        const take = Math.min(b.length, max - read);
        read += take;
        this.bytes += take;
        const text = tail + b.toString('latin1', 0, take);
        this.look(text, name, o);
        tail = text.slice(-OVERLAP);
        if (read >= max || Date.now() > this.until) {
          if (read < size) this.capped = true;
          break;
        }
      }
    } catch {
      // A broken entry: what was read still counts.
    }
    this.endFile(name);
  }

  /** A file already in memory (Info.plist, the primary classes.dex). */
  buffer(data: Uint8Array, file: string, o: Opts = {}) {
    if (this.stopped) {
      this.capped = true;
      return;
    }
    const b = buf(data);
    this.files++;
    const max = Math.min(b.length, this.allowance());
    if (max < b.length) this.capped = true;
    this.bytes += max;
    for (let i = 0; i < max; i += 8 * 1024 * 1024) {
      const start = Math.max(0, i - OVERLAP);
      this.look(b.toString('latin1', start, Math.min(max, i + 8 * 1024 * 1024)), file, o);
    }
    this.endFile(file);
  }

  common(): Omit<SecurityFacts, 'android' | 'ios'> {
    const google = [...this.googleKeys.values()];
    // One entry per distinct key: the same key in several files is listed once with its first file.
    const seen = new Set<string>();
    const keys = google.filter((h) => !seen.has(h.masked) && seen.add(h.masked)).slice(0, MAX_GOOGLE_KEYS);
    return {
      secrets: [...this.secrets.values(), ...keys],
      rasp: [...this.rasp].sort(),
      libs: [...this.libs.values()],
      scan: { files: this.files, bytes: this.bytes, capped: this.capped },
    };
  }
}

// ---------------------------------------------------------------- Android

export type XNode = { tag: string; attrs: Record<string, string>; children: XNode[]; parent: XNode | null };

/** `aapt2 dump xmltree` output as a tree of elements with plain attribute values. */
export function xmlTree(dump: string): XNode | null {
  const root: XNode = { tag: '#root', attrs: {}, children: [], parent: null };
  const stack: { indent: number; node: XNode }[] = [{ indent: -1, node: root }];
  for (const line of dump.split('\n')) {
    const el = /^(\s*)E: ([\w.:-]+)/.exec(line);
    if (el) {
      const indent = el[1].length;
      while (stack.length > 1 && stack[stack.length - 1].indent >= indent) stack.pop();
      const parent = stack[stack.length - 1].node;
      const node: XNode = { tag: el[2], attrs: {}, children: [], parent };
      parent.children.push(node);
      stack.push({ indent, node });
      continue;
    }
    const at = /^(\s*)A: (.*)$/.exec(line);
    if (!at) continue;
    const indent = at[1].length;
    while (stack.length > 1 && stack[stack.length - 1].indent >= indent) stack.pop();
    const node = stack[stack.length - 1].node;
    if (node === root) continue;
    const eq = at[2].indexOf('=');
    if (eq < 0) continue;
    const name = at[2].slice(0, eq).replace(/\(0x[0-9a-f]+\)$/, '').split(':').pop()!;
    node.attrs[name] = attrValue(at[2].slice(eq + 1));
  }
  return root.children.length ? root : null;
}

function attrValue(raw: string): string {
  const q = /^"(.*)" \(Raw: "/.exec(raw)?.[1] ?? /^"(.*)"$/.exec(raw)?.[1];
  if (q !== undefined) return q;
  const t = /^\(type 0x12\)(0x[0-9a-f]+)$/.exec(raw);
  if (t) return t[1] === '0x0' ? 'false' : 'true';
  return raw.replace(/^\(type [^)]*\)/, '');
}

function* walk(n: XNode): Generator<XNode> {
  yield n;
  for (const c of n.children) yield* walk(c);
}

const COMPONENTS = new Set(['activity', 'activity-alias', 'service', 'receiver', 'provider']);

/** Exported components without a permission; the launcher activity (and TV launcher) is left out. */
export function exportedComponents(tree: XNode | null): { list: AndroidSecurity['exported']; total: number } {
  if (!tree) return { list: [], total: 0 };
  const manifest = [...walk(tree)].find((n) => n.tag === 'manifest');
  const pkg = manifest?.attrs.package ?? '';
  const app = [...walk(tree)].find((n) => n.tag === 'application');
  if (!app) return { list: [], total: 0 };
  const out: AndroidSecurity['exported'] = [];
  let total = 0;
  for (const c of app.children) {
    if (!COMPONENTS.has(c.tag) || c.attrs.enabled === 'false') continue;
    const filters = c.children.filter((x) => x.tag === 'intent-filter');
    const exported = c.attrs.exported === 'true' || (c.attrs.exported === undefined && c.tag !== 'provider' && filters.length > 0);
    if (!exported) continue;
    const guarded = !!c.attrs.permission || (c.tag === 'provider' && (!!c.attrs.readPermission || !!c.attrs.writePermission));
    if (guarded) continue;
    const launcher = filters.some((f) => {
      const actions = f.children.filter((x) => x.tag === 'action').map((x) => x.attrs.name);
      const cats = f.children.filter((x) => x.tag === 'category').map((x) => x.attrs.name);
      return actions.includes('android.intent.action.MAIN') && cats.some((x) => x === 'android.intent.category.LAUNCHER' || x === 'android.intent.category.LEANBACK_LAUNCHER');
    });
    if (launcher && (c.tag === 'activity' || c.tag === 'activity-alias')) continue;
    total++;
    const raw = c.attrs.name ?? '';
    const name = raw.startsWith('.') ? `${pkg}${raw}` : raw.includes('.') || !pkg ? raw : `${pkg}.${raw}`;
    if (out.length < MAX_EXPORTED) out.push({ kind: c.tag as AndroidSecurity['exported'][number]['kind'], name: name.slice(0, 200) });
  }
  return { list: out, total };
}

/** A network security config trusts user added CAs (src="user") outside debug-overrides. */
export function trustsUserCerts(tree: XNode | null): boolean {
  if (!tree) return false;
  for (const n of walk(tree)) {
    if (n.tag !== 'certificates' || n.attrs.src !== 'user') continue;
    let p = n.parent;
    let debugOnly = false;
    while (p) {
      if (p.tag === 'debug-overrides') debugOnly = true;
      p = p.parent;
    }
    if (!debugOnly) return true;
  }
  return false;
}

/** File path of a resource id ("@0x7f130000") in `aapt2 dump resources` output. */
export function resourcePath(dump: string, ref: string): string | null {
  const id = /^@?(0x[0-9a-f]{8})$/.exec(ref)?.[1];
  if (!id) return null;
  const lines = dump.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (!new RegExp(`^\\s*resource ${id}\\b`).test(lines[i])) continue;
    for (let j = i + 1; j < lines.length && !/^\s*(resource|type) /.test(lines[j]); j++) {
      const m = /\(file\) (\S+)/.exec(lines[j]);
      if (m) return m[1];
    }
  }
  return null;
}

/**
 * R8 / ProGuard hint from a dex file: the classes it defines and how many have a one or two letter name
 * (inner class parts ignored). Null when the file is not a dex or too small to tell.
 */
export function dexMinify(data: Uint8Array): { classes: number; short: number } | null {
  const b = buf(data);
  if (b.length < 0x70 || b.toString('latin1', 0, 4) !== 'dex\n') return null;
  const stringIdsSize = b.readUInt32LE(0x38);
  const stringIdsOff = b.readUInt32LE(0x3c);
  const typeIdsSize = b.readUInt32LE(0x40);
  const typeIdsOff = b.readUInt32LE(0x44);
  const classDefsSize = b.readUInt32LE(0x60);
  const classDefsOff = b.readUInt32LE(0x64);
  const n = Math.min(classDefsSize, 20_000);
  let classes = 0;
  let short = 0;
  for (let i = 0; i < n; i++) {
    const cd = classDefsOff + i * 32;
    if (cd + 4 > b.length) break;
    const typeIdx = b.readUInt32LE(cd);
    if (typeIdx >= typeIdsSize || typeIdsOff + typeIdx * 4 + 4 > b.length) continue;
    const strIdx = b.readUInt32LE(typeIdsOff + typeIdx * 4);
    if (strIdx >= stringIdsSize || stringIdsOff + strIdx * 4 + 4 > b.length) continue;
    let p = b.readUInt32LE(stringIdsOff + strIdx * 4);
    if (p >= b.length) continue;
    // uleb128 length (UTF-16 units), then MUTF-8 bytes ending in 0.
    while (p < b.length && b[p] & 0x80) p++;
    p++;
    const end = b.indexOf(0, p);
    if (end < 0) continue;
    const desc = b.toString('latin1', p, Math.min(end, p + 300));
    const m = /^L(?:[^;]*\/)?([^/;]+);$/.exec(desc);
    if (!m) continue;
    classes++;
    const simple = m[1].split('$')[0];
    if (/^[A-Za-z]{1,2}$/.test(simple)) short++;
  }
  return classes >= 20 ? { classes, short } : null;
}

const ABI_ORDER = ['arm64-v8a', 'armeabi-v7a', 'x86_64', 'x86'];

export type AndroidInput = {
  /** The manifest as a tree (aapt2 xmltree in the worker, the binary XML in the CLI). */
  tree: XNode | null;
  /** Whether the network security config trusts user CAs; null when there is none or it was not read. */
  userCerts?: () => Promise<boolean | null>;
};

export async function scanAndroid(zip: ScanZip, input: AndroidInput, limits: ScanLimits = LIMITS): Promise<SecurityFacts> {
  const s = new Scan(limits);
  const tree = input.tree;
  const app = tree ? [...walk(tree)].find((n) => n.tag === 'application') : undefined;
  const a = app?.attrs ?? {};
  const all = zip.names();

  // Library versions from META-INF/<group>_<artifact>.version (AndroidX, Google Play services, Firebase, Play Core).
  for (const name of all.filter((x) => /^META-INF\/[^/]+\.version$/.test(x)).slice(0, MAX_LIBS)) {
    if (zip.size(name) > 1024) continue;
    const v = buf((await zip.read(name, 1024).catch(() => null)) ?? new Uint8Array()).toString('utf8').trim();
    const base = name.slice('META-INF/'.length, -'.version'.length);
    const cut = base.indexOf('_');
    if (v && cut > 0) s.lib(`${base.slice(0, cut)}:${base.slice(cut + 1)}`, v);
  }

  let minify: AndroidSecurity['minify'] = null;
  const dex = all.filter((x) => /^classes\d*\.dex$/.test(x)).sort((x, y) => x.length - y.length || x.localeCompare(y));
  const first = dex[0];
  if (first && zip.size(first) <= Math.min(96 * 1024 * 1024, s.allowance())) {
    const data = await zip.read(first, 96 * 1024 * 1024).catch(() => null);
    if (data) {
      minify = dexMinify(data);
      s.buffer(data, first, { dex: true });
    }
  } else if (first) await s.entry(zip, first, { dex: true });
  for (const name of dex.slice(1)) await s.entry(zip, name, { dex: true });

  if (all.includes('resources.arsc')) await s.entry(zip, 'resources.arsc', { utf16: true });
  // An .aab keeps its resource table as protobuf (UTF-8 strings); only the CLI check reads bundles directly.
  if (all.includes('resources.pb')) await s.entry(zip, 'resources.pb');

  const assets = all
    .filter((x) => /^(assets|res\/raw)\//.test(x) && !MEDIA.test(x))
    .sort((x, y) => Number(/\.bundle$|\.js$/.test(y)) - Number(/\.bundle$|\.js$/.test(x)) || zip.size(x) - zip.size(y));
  for (const name of assets) await s.entry(zip, name);

  const abi = ABI_ORDER.find((x) => all.some((n) => n.startsWith(`lib/${x}/`)));
  if (abi) {
    const libs = all
      .filter((n) => n.startsWith(`lib/${abi}/`) && n.endsWith('.so'))
      .sort((x, y) => Number(y.endsWith('/libapp.so')) - Number(x.endsWith('/libapp.so')) || zip.size(x) - zip.size(y));
    for (const name of libs) await s.entry(zip, name, { native: true });
  }

  const userCerts = a.networkSecurityConfig && input.userCerts ? await input.userCerts().catch(() => null) : null;
  const exported = exportedComponents(tree);
  return {
    ...s.common(),
    android: {
      allowBackup: a.allowBackup === undefined ? null : a.allowBackup === 'true',
      backupRules: a.dataExtractionRules !== undefined || a.fullBackupContent !== undefined,
      exported: exported.list,
      exportedTotal: exported.total,
      minify,
      webviewDebug: s.webview,
      userCerts,
    },
  };
}

// ---------------------------------------------------------------- iOS

/** Local symbols (LC_DYSYMTAB nlocalsym) of a Mach-O, thin or fat (the arm64 slice); null when unreadable. */
export function machoLocalSymbols(data: Uint8Array): number | null {
  const h = buf(data);
  if (h.length < 32) return null;
  let off = 0;
  const be = h.readUInt32BE(0);
  if (be === 0xcafebabe || be === 0xcafebabf) {
    const n = Math.min(h.readUInt32BE(4), 8);
    const size = be === 0xcafebabf ? 32 : 20;
    off = -1;
    for (let i = 0; i < n && 8 + i * size + size <= h.length; i++) {
      const at = 8 + i * size;
      const o = be === 0xcafebabf ? Number(h.readBigUInt64BE(at + 8)) : h.readUInt32BE(at + 8);
      if (h.readUInt32BE(at) === 0x0100000c) {
        off = o;
        break;
      }
      if (off < 0) off = o;
    }
  }
  if (off < 0 || off + 32 > h.length) return null;
  const magic = h.readUInt32LE(off);
  if (magic !== 0xfeedfacf && magic !== 0xfeedface) return null;
  const ncmds = h.readUInt32LE(off + 16);
  let p = off + (magic === 0xfeedfacf ? 32 : 28);
  for (let i = 0; i < ncmds && p + 16 <= h.length; i++) {
    const cmd = h.readUInt32LE(p);
    const size = h.readUInt32LE(p + 4);
    if (cmd === 0xb) return h.readUInt32LE(p + 12);
    if (size < 8) break;
    p += size;
  }
  return null;
}

/** App Transport Security exception domains with what each one loosens. */
export function atsExceptions(info: Dict): IosSecurity['atsExceptions'] {
  const ats = (info.NSAppTransportSecurity ?? {}) as Dict;
  const domains = (ats.NSExceptionDomains ?? {}) as Dict;
  return Object.entries(domains)
    .slice(0, 20)
    .map(([domain, v]) => {
      const d = (v ?? {}) as Dict;
      const tls = d.NSExceptionMinimumTLSVersion ?? d.NSTemporaryExceptionMinimumTLSVersion;
      return {
        domain: domain.slice(0, 200),
        insecureHttp: d.NSExceptionAllowsInsecureHTTPLoads === true || d.NSTemporaryExceptionAllowsInsecureHTTPLoads === true,
        minTls: typeof tls === 'string' ? tls.slice(0, 20) : null,
        noForwardSecrecy: d.NSExceptionRequiresForwardSecrecy === false || d.NSTemporaryExceptionRequiresForwardSecrecy === false,
        subdomains: d.NSIncludesSubdomains === true,
      };
    });
}

const IOS_SKIP = /^(Frameworks|PlugIns|Watch|_CodeSignature|SC_Info|Extensions)\//;

/** `parsePlist`: XML or binary plist bytes to a dictionary (the caller's parser). */
export async function scanIos(zip: ScanZip, appDir: string, info: Dict, parsePlist: (b: Uint8Array) => Dict | null, limits: ScanLimits = LIMITS): Promise<SecurityFacts> {
  const s = new Scan(limits);
  const rel = zip.names().filter((n) => n.startsWith(appDir)).map((n) => n.slice(appDir.length));
  const has = new Set(rel);

  if (has.has('Info.plist')) {
    const data = await zip.read(`${appDir}Info.plist`, 4 * 1024 * 1024).catch(() => null);
    if (data) s.buffer(data, 'Info.plist');
  }

  let localSymbols: number | null = null;
  const exeName = typeof info.CFBundleExecutable === 'string' ? info.CFBundleExecutable : null;
  if (exeName && has.has(exeName)) {
    localSymbols = machoLocalSymbols(await zip.head(`${appDir}${exeName}`, 1024 * 1024).catch(() => new Uint8Array()));
    await s.entry(zip, `${appDir}${exeName}`, { iosBinary: true });
  }

  // Framework versions (Info.plist) and protection libraries shipped as frameworks.
  const fws = [...new Set(rel.map((r) => /^Frameworks\/([^/]+)\.framework\//.exec(r)?.[1]).filter((x): x is string => !!x))];
  for (const fw of fws.slice(0, 120)) {
    for (const [re, name] of IOS_RASP_FRAMEWORKS) if (re.test(fw)) s.rasp.add(name);
    const path = `${appDir}Frameworks/${fw}.framework/Info.plist`;
    if (!has.has(`Frameworks/${fw}.framework/Info.plist`) || zip.size(path) > 256 * 1024) continue;
    const p = parsePlist((await zip.read(path, 256 * 1024).catch(() => null)) ?? new Uint8Array());
    const v = p?.CFBundleShortVersionString;
    if (typeof v === 'string' && v.trim()) s.lib(fw, v.trim());
  }

  const files = rel
    .filter((r) => r !== 'Info.plist' && r !== exeName && !IOS_SKIP.test(r) && !MEDIA.test(r) && !/\.(storyboardc|lproj\/[^/]+\.nib)\b/.test(r) && !r.endsWith('embedded.mobileprovision'))
    .map((r) => appDir + r)
    .sort((x, y) => Number(/\.jsbundle$/.test(y)) - Number(/\.jsbundle$/.test(x)) || zip.size(x) - zip.size(y));
  for (const name of files) await s.entry(zip, name);

  // Flutter: Dart code (and the strings in it) lives in App.framework.
  if (has.has('Frameworks/App.framework/App')) await s.entry(zip, `${appDir}Frameworks/App.framework/App`);

  return {
    ...s.common(),
    ios: {
      atsExceptions: atsExceptions(info),
      atsWebContent: ((info.NSAppTransportSecurity ?? {}) as Dict).NSAllowsArbitraryLoadsInWebContent === true,
      localSymbols,
      getTaskAllow: s.getTaskAllow,
    },
  };
}
